fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // Preconditions (as stated in the problem); kept as debug asserts.
    debug_assert!(c >= 0);
    debug_assert!(f >= -1);
    debug_assert!((c as usize) <= v.len());
    debug_assert!((f + 1) as usize <= v.len());
    debug_assert!(c <= f + 1);

    // Base case: unresolved interval is empty => answer is the last known <= elem index.
    if c > f {
        return c - 1; // may be -1
    }

    // Compute mid without overflow: mid = floor((c + f) / 2)
    let mid = c + (f - c) / 2;
    debug_assert!(mid >= 0 && (mid as usize) < v.len());

    if v[mid as usize] <= elem {
        // mid is <= elem, so the last <= elem is in [mid+1 .. f] or is mid.
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // mid is > elem, so the last <= elem is in [c .. mid-1].
        binary_search_recursive(v, elem, c, mid - 1)
    }
}